// Prefer a real Google Meet link if the Calendar call produced one;
// otherwise generate an instant Jitsi room so the button always works
// (no credential or Google Cloud setup required).
const j = $input.first().json || {};
let link = j.hangoutLink ||
  ((j.conferenceData && j.conferenceData.entryPoints && j.conferenceData.entryPoints[0])
    ? j.conferenceData.entryPoints[0].uri : '');
if (!link) {
  const body = ($('Webhook').first().json.body) || {};
  const slug = String(body.applicant_name || 'meet').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 24) || 'meet';
  const rand = Math.random().toString(36).slice(2, 8);
  link = `https://meet.jit.si/HIRE-${slug}-${rand}`;
}
return [{ json: { meet_link: link } }];
